def answer_units(answer):
    out = []
    values = answer.get('selected_evidence_unit_ids', [])
    if isinstance(values, list):
        for value in values:
            if type(value) is int and value not in out:
                out.append(value)
    evidence = answer.get('evidence', [])
    if isinstance(evidence, list):
        for item in evidence:
            if isinstance(item, dict) and type(item.get('unit_id')) is int and item.get('unit_id') not in out:
                out.append(item.get('unit_id'))
    return out

def answer_anchor(answer):
    identity = answer.get('id', '')
    if not isinstance(identity, str) or '|unit|' not in identity:
        return ''
    return identity.rsplit('|unit|', 1)[1]

def source_words(ids, spans):
    parts = []
    for span in spans:
        if isinstance(span, dict) and span.get('id') in ids and isinstance(span.get('text'), str):
            parts.append(span.get('text'))
    return ' '.join(parts)

def participant_union(items):
    if not items:
        return None
    value = items[0]
    i = 1
    while i < len(items):
        value = ['participant_union', value, items[i]]
        i += 1
    return value

def recipient_term(choice):
    receiver = ['receiving_party']
    if choice == 'recipient_own_employees_officers_directors':
        return participant_union([['employees_of', receiver], ['officers_of', receiver], ['directors_of', receiver]])
    if choice == 'recipient_own_employees_directors_contractors':
        return participant_union([['employees_of', receiver], ['directors_of', receiver], ['independent_contractors_of', receiver]])
    if choice == 'recipient_own_employees_and_consultants':
        return participant_union([['employees_of', receiver], ['consultants_of', receiver]])
    if choice == 'recipient_affiliate_officers_directors_employees':
        owner = ['affiliates_of', receiver]
        return participant_union([['employees_of', owner], ['officers_of', owner], ['directors_of', owner]])
    if choice == 'recipient_own_and_controlled_personnel':
        controlled = ['controlled_entities_of', receiver]
        own = participant_union([['employees_of', receiver], ['officers_of', receiver], ['directors_of', receiver], ['representatives_of', receiver], ['agents_of', receiver]])
        related = participant_union([['employees_of', controlled], ['officers_of', controlled], ['directors_of', controlled], ['representatives_of', controlled], ['agents_of', controlled]])
        return ['participant_union', own, related]
    if choice == 'unrestricted_third_parties':
        return ['third_parties']
    return None

def material_term(choice):
    info = ['confidential_information']
    copies = ['copies_of', info]
    if choice == 'confidential_information_only':
        return info
    if choice in ('confidential_information_and_copies', 'stated_materials_and_copies'):
        return ['information_bundle', info, copies]
    if choice == 'information_copies_and_derivatives':
        return ['information_bundle', ['information_bundle', info, copies], ['derivative_materials_of', info]]
    return None

def trigger_term(choice):
    request = ['request_by', ['disclosing_party']]
    if choice == 'agreement_termination_or_counterparty_request':
        return ['trigger_alternative', ['agreement_termination'], request]
    if choice == 'purpose_completion_or_counterparty_request':
        return ['trigger_alternative', ['purpose_completion'], request]
    if choice == 'relationship_nonformation_deadline_or_counterparty_request':
        return ['trigger_alternative', ['relationship_nonformation_deadline'], request]
    if choice == 'counterparty_request_only':
        return request
    if choice == 'agreement_termination_only':
        return ['agreement_termination']
    return None

def append_fragment(rows, term, supports, queries):
    if term is None or not supports or not queries:
        return
    row = {'term': term, 'support_ids': sorted(set(supports)), 'query_ids': list(queries)}
    key = repr(row)
    for old in rows:
        if repr(old) == key:
            return
    rows.append(row)

def apply(inputs, premises):
    spans = inputs.get('source_spans', [])
    answers = inputs.get('semantic_answers', [])
    groups = {}
    for answer in answers:
        if not isinstance(answer, dict) or answer.get('choice') in (None, 'unknown'):
            continue
        anchor = answer_anchor(answer)
        operation = answer.get('operation')
        if not anchor or not isinstance(operation, str):
            continue
        groups.setdefault(anchor, {})[operation] = answer
    fragments = []
    unresolved = []
    for anchor, group in groups.items():
        modality = group.get('disclosure_modality')
        recipient = group.get('disclosure_recipient_scope')
        condition = group.get('disclosure_conditions')
        if modality is not None and recipient is not None:
            shared = sorted(set(answer_units(modality)).intersection(set(answer_units(recipient))))
            receiver = recipient_term(recipient.get('choice'))
            mode = modality.get('choice')
            if receiver is not None and mode in ('operative_class_permission', 'operative_general_prohibition', 'prohibition_with_embedded_class_permission') and shared:
                action = ['disclose', ['confidential_information'], receiver]
                append_fragment(fragments, action, shared, [modality.get('id'), recipient.get('id')])
            elif mode != 'not_an_operative_disclosure_rule':
                unresolved.append('disclosure action at current anchor ' + anchor)
        if condition is not None:
            supports = answer_units(condition)
            wording = source_words(supports, spans)
            if condition.get('choice') == 'need_to_know_and_confidentiality_bound' and supports:
                term = ['and_condition', ['need_to_know', wording], ['confidentiality_bound', wording]]
                append_fragment(fragments, term, supports, [condition.get('id')])
            elif condition.get('choice') == 'no_additional_condition' and supports:
                append_fragment(fragments, ['no_condition'], supports, [condition.get('id')])
        action_answer = group.get('disposal_action')
        material_answer = group.get('disposal_material_scope')
        if action_answer is not None and material_answer is not None:
            shared = sorted(set(answer_units(action_answer)).intersection(set(answer_units(material_answer))))
            material = material_term(material_answer.get('choice'))
            wording = source_words(shared, spans)
            action_choice = action_answer.get('choice')
            action = None
            if material is not None and action_choice == 'return_only':
                action = ['return_to', material, ['disclosing_party']]
            elif material is not None and action_choice == 'destroy_only':
                action = ['destroy', material]
            elif material is not None and action_choice == 'return_or_destroy_unallocated':
                action = ['action_alternative', ['return_to', material, ['disclosing_party']], ['destroy', material]]
            elif material is not None and action_choice == 'return_or_destroy_at_counterparty_option':
                action = ['source_action_alternative', ['return_to', material, ['disclosing_party']], ['destroy', material], wording]
            elif material is not None and action_choice == 'return_or_destroy_with_authorization_on_destroy':
                action = ['source_authorized_action_alternative', ['return_to', material, ['disclosing_party']], ['destroy', material], wording]
            if action is not None and shared:
                append_fragment(fragments, action, shared, [action_answer.get('id'), material_answer.get('id')])
            elif action_choice != 'other_or_no_disposal_action':
                unresolved.append('disposal action or material at current anchor ' + anchor)
        trigger_answer = group.get('disposal_trigger')
        if trigger_answer is not None:
            supports = answer_units(trigger_answer)
            trigger = trigger_term(trigger_answer.get('choice'))
            if trigger is not None and supports:
                append_fragment(fragments, trigger, supports, [trigger_answer.get('id')])
            elif trigger_answer.get('choice') != 'other_or_no_disposal_trigger':
                unresolved.append('disposal trigger at current anchor ' + anchor)
        retention = group.get('retention_effect')
        if retention is not None:
            supports = answer_units(retention)
            wording = source_words(supports, spans)
            choice = retention.get('choice')
            if choice == 'no_explicit_exception_in_complete_disposal_clause' and supports:
                append_fragment(fragments, ['no_exceptions'], supports, [retention.get('id')])
            elif choice in ('archival_copy_permission', 'qualified_retention_permission') and supports:
                info = ['copies_of', ['confidential_information']] if choice == 'archival_copy_permission' else ['confidential_information']
                condition_term = ['retention_condition', wording]
                exception = ['exception_set', ['retention_exception', ['receiving_party'], info, condition_term]]
                append_fragment(fragments, exception, supports, [retention.get('id')])
                append_fragment(fragments, info, supports, [retention.get('id')])
                append_fragment(fragments, condition_term, supports, [retention.get('id')])
                append_fragment(fragments, ['after_disposal'], supports, [retention.get('id')])
            elif choice == 'explicit_post_disposal_retention_prohibition' and supports:
                append_fragment(fragments, ['confidential_information'], supports, [retention.get('id')])
                append_fragment(fragments, ['after_disposal'], supports, [retention.get('id')])
            elif choice != 'other_or_unresolved_retention_effect':
                unresolved.append('retention effect at current anchor ' + anchor)
    return {'fragments': fragments, 'unresolved': unresolved}

